from pathlib import Path
import json,collections
root=Path('research/admissions-120');records=json.loads((root/'requirements.json').read_text(encoding='utf8'))
metrics={'contentReviewed':len(records),'catalogueInventory':540,'countries':{},'definitions':{'clearLanguage':'At least one scoped accepted test/waiver/institutional assessment or explicit local-language qualification; not a claim of a verified 2027 numerical minimum.','establishedAcademicPolicy':'At least one scoped policy other than unknown/conflict/acceptance-only; exceptions and previous-cycle rules remain marked.','remaining':'Cards with documented unresolved fields; this is not a count of factual errors.'}}
for country in ['us','ca','uk','de','jp','kr']:
 rows=[x for x in records.values() if x['country']==country]
 metrics['countries'][country]={'reviewed':len(rows),'clearLanguage':sum(any(r['localLanguage'] or r['english'].get('requirement') in ['internal-assessment','optional'] or any((r['english'].get(t) or {}).get('accepted') is True for t in ['ielts','toefl']) for r in x['routes']) for x in rows),'establishedAcademicPolicy':sum(any(r['academic'].get('satPolicy','unknown') not in ['unknown','conflict','accepted'] for r in x['routes']) for x in rows),'exactIeltsSections':sum(any((r['english'].get('ielts') or {}).get('sections') for r in x['routes']) for x in rows),'cardsWithRemainingFields':sum(bool(x['unknown']) for x in rows)}
(root/'metrics.json').write_text(json.dumps(metrics,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
checks={
'us':{'wheaton-college-massachusetts':'6.5 is recommended; academic SAT/ACT optional; four-year school waiver is conditional.','wheaton-college-illinois':'Undergraduate PDF 1–4: unresolved 7–8 range is not reduced to an invented universal cutoff; homeschool academic condition remains.','the-college-of-new-jersey':'2026–27 testing page retains Nursing/7-year exceptions; IELTS 7 is recommended; calculus placement is not admission.'},
'ca':{'brock-university':'General 6.5/6 versus BAcc 7/6.5, and inconsistent January TOEFL wording remain scoped.','mount-royal-university':'6.5/5.5, school English prerequisite independent, two-year qualifying school route.','wilfrid-laurier-university':'6.5/6, three recent non-ESL English years; conditional offer is not unconditional entry.'},
'uk':{'middlesex-university':'Undergraduate 6/5.5 column, professional exceptions; PTE Academic 59 in the full table, not another test 51.','coventry-university':'Computer Science BSc Coventry 2027/28, 6/5.5; pre-sessional and integrated Foundation separate.','de-montfort-university':'Computing/Engineering/Art reference category 6; national pages and other faculties differ, not universal 6.'},
'de':{'rhine-waal-university':'One-page B2/C1 table: IELTS 5.5 vs 7, legacy TOEFL72 vs95; B2 bachelor scope stays undated.','technical-university-of-munich':'DSH2/TestDaF4 each, named Aerospace/Information exceptions; six bachelor aptitude-assessed English exceptions, not universal IELTS6.5.','anhalt-university':'International Business BA Bernburg: separate English 6.5/TOEFL88 and German-language branch; not every Anhalt course.'},
'jp':{'osaka-university':'Human Sciences October2027: overall6.5, generally sections6 remains qualified; no SISC or university-wide claim.','nagoya-university':'AY2027 Appendix1 p30: Academic6, OSR allowed, TOEFL80/4, DET110; academic eligibility exceptions independent.','hosei-university':'GBP2027: Academic6, noOSR/Online/Indicator, academic alternatives compulsory. No spread to GIS/SCOPE.'},
'kr':{'kaist':'2027 guide: 6.5 recommended while report required; separate compulsory SAT/ACT/other academic alternative.','sejong-university':'Spring2027 guide: English5.5 and citizenship waiver restriction; TOPIK levels by department, not Fall2027 confirmation.','pusan-national-university':'Spring2027 English Global Studies, nationality exceptions7 and Korean AI not an English track; no universal5.5.'}}
out=[]
for country,items in checks.items():
 for uid,note in items.items():
  out.append({'id':uid,'country':country,'checked':'2026-11-19','result':'Scoped facts agree with read official sections; remaining questions retained','comparison':note,'sources':list(dict.fromkeys(s['url'] for r in records[uid]['routes'] for s in r['sources']))})
(root/'self-review-18.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
p=root/'progress.md';p.write_text(p.read_text(encoding='utf8')+'\n\n## v257 — первая партия 120 записей завершена по источникам\n\n60 US, 15 CA, 15 UK, 10 DE, 10 JP, 10 KR. Dordt/Inha/Konkuk не засчитаны: причины и замены из существующего каталога сохранены в blocked-queue.json. Все карточки имеют индивидуальные ограничения. Сверка 18 записей по 3 на страну — self-review-18.json. Исправлен общий ложный положительный результат IELTS для местного языка и добавлено предупреждение о непроверенных академических предметах/минимумах даже при введённом тесте. 617 passed, 0 failed.\n\nСледующий этап: точные production и staging сборки v257, внутренние ссылки, все 120 маршрутов RU/EN, полноценные сценарии сохранения/сравнения/календаря, ревью diff и опубликованный staging. Эта запись ещё не объявляет их выполненными.\n',encoding='utf8')
p=Path('AUDIT_EXPANSION_PROGRESS.md');p.write_text(p.read_text(encoding='utf8')+'\n\n## v257 — требования 120 существующих вузов, 19 ноября 2026\nПервая партия 60 US / 15 CA / 15 UK / 10 DE / 10 JP / 10 KR: применимые официальные разделы прочитаны, маршруты RU/EN уточнены. 617 passed, 0 failed. Местный язык не получает положительную отметку от одного IELTS; секции и академические квалификации независимы. Подробные источники, неизвестные поля, 18 повторных сверок и протоколы — research/admissions-120. Финальная браузерная проверка и staging выполняются следующим этапом. Main и PR №27 не изменены.\n',encoding='utf8')
